namespace CheckoutPricing.Domain;

public static class DiscountPolicy
{
    public static int TotalDiscountFor(LoyaltyTier tier, int subtotalCents, string? promoCode)
    {
        var loyalty = LoyaltyDiscountPolicy.DiscountFor(tier, subtotalCents);
        var promo = PromoCodePolicy.DiscountFor(promoCode, subtotalCents - loyalty);
        return Math.Min(loyalty + promo, subtotalCents);
    }
}
